-- 作成日時を少しずつ過去に（作成日時の書き換えはトリガで拒否されるので、一時的に外す）
alter table public.posts disable trigger posts_only_count_update;
update public.posts set created_at = now() - interval '3 hours' where id = (select id from showcase_posts where k = 0);
update public.posts set created_at = now() - interval '9 hours' where id = (select id from showcase_posts where k = 1);
update public.posts set created_at = now() - interval '20 hours' where id = (select id from showcase_posts where k = 2);
update public.posts set created_at = now() - interval '30 hours' where id = (select id from showcase_posts where k = 3);
update public.posts set created_at = now() - interval '44 hours' where id = (select id from showcase_posts where k = 4);
update public.posts set created_at = now() - interval '60 hours' where id = (select id from showcase_posts where k = 5);
alter table public.posts enable trigger posts_only_count_update;

select count(*) as showcase_posts, sum(answer_count) as showcase_answers from public.posts where author_uid::text like '00000000-0000-0000-5eed-%';
commit;
